def tr_lower(s):
    """Türkçe kurallarına göre stringi küçük harfe çevirir."""
    # Türkçe karakter dönüşümü
    i_map = {'I': 'ı', 'İ': 'i'}
    result = ""
    for char in s:
        if char in i_map:
            result += i_map[char]
        else:
            result += char.lower()
    return result

def tr_upper(s):
    """Türkçe kurallarına göre stringi büyük harfe çevirir."""
    # Türkçe karakter dönüşümü
    i_map = {'ı': 'I', 'i': 'İ'}
    result = ""
    for char in s:
        if char in i_map:
            result += i_map[char]
        else:
            result += char.upper()
    return result

def tr_sorted(words):
    """Kelime listesini Türkçe alfabesine göre sıralar."""
    # Türkçe alfabe sırası
    turk_alphabet = "0123456789abcçdefgğhıijklmnoöpqrsştuüvwxyz"

    def sort_key(word):
        # Kelimenin küçük harfle yazılmış hali
        lower_word = tr_lower(word)

        # Karakter sıralamasını oluştur
        key_parts = []
        for char in lower_word:
            if char in turk_alphabet:
                key_parts.append(f"0{turk_alphabet.index(char)}")  # Sıra numarası
            else:
                # Diğer karakterler Unicode koduna göre sıralanır, ama önce gelir
                key_parts.append(f"1{ord(char):06d}")  # "1" ile başlayarak sıralama

        return tuple(key_parts)

    # Kelimeleri sıralayın ama orijinal listeyi değiştirmeyin
    sorted_words = sorted(words, key=sort_key)

    return sorted_words

